  b = `คุณไม่สามารถเปลี่ยนหมวดหมู่ของหน้าหลักผู้สร้าง`,
  x = `คุณไม่สามารถเปลี่ยนหมวดหมู่ของอัปเดตสำคัญที่เกี่ยวข้องกับข้อความทางการตลาด`,
  S = `อัปเดตเกม`,
  C = `แจ้งให้ผู้เล่นทราบเกี่ยวกับการอัปเดตไม่ว่าเล็กหรือใหญ่; เนื้อหาใหม่ การเปลี่ยนแปลงฟังก์ชันการทำงาน หรือการแก้ไขจุดบกพร่อง`,
  w = `เชิญบรรดาแฟน ๆ ของคุณให้มาร่วมสังสรรค์ แช็ต พบปะกับทีมผู้พัฒนา ถามคำถาม`,
