  I = `ประกาศให้ทราบเกี่ยวกับผู้เล่นที่มีสิทธิ์ได้รับโบนัสหรือกิจกรรมเพิร์คแบบจำกัดเวลาภายในเกมด้วยการบรรลุภารกิจ และ/หรือมีส่วนร่วมในกิจกรรมชุมชน`,
  L = `การท้าทายรายวัน รายสัปดาห์ รายเดือน หรือการท้าทายพิเศษ`,
  R = `ขอให้บรรดาแฟน ๆ ของคุณกระทำการบางอย่างเพื่อเข้าร่วมประกวด ซึ่งอาจเป็นการประกวดอาร์ตเวิร์ก? ผลงานนำเสนอในเวิร์กชอป? เกมแข่งขันแบบผู้เล่นหลายคน?`,
  z = `เชิญบรรดาแฟน ๆ ของคุณให้มาร่วมสังสรรค์กันในชีวิตจริง หรือแจ้งให้แฟน ๆ ทราบหากคุณกำลังมุ่งหน้าไปยังสถานที่ที่น่าสนใจ`,
  B = `แจ้งให้ผู้เล่นทราบถึงข่าวที่น่าสนใจ การบรรลุหลักชัยที่น่าปลาบปลื้ม? หรือกำลังทำอะไรบางสิ่งที่น่าสนใจอยู่?`,
