  de = `กิจกรรมเพิร์ค รางวัล หรือโบนัสพิเศษ`,
  fe = `เชิญชวนให้ผู้ติดตามลองเล่นเกมของคุณเพื่อรับชุดรางวัลหรือโบนัสพิเศษ`,
  pe = `ประกาศถึงกิจกรรมแบบจำกัดเวลาในเกมของคุณ ซึ่งผู้เล่นจะได้รับไอเท็มพิเศษ โบนัส กิจกรรมเพิร์ค รางวัล XP ฯลฯ โดยมีเวลาเริ่มต้นและเวลาสิ้นสุด`,
  me = `เลือกประเภทของกิจกรรม`,
  he = `ท้าทายหรือประกวด`,
  ge = `ท้าทายผู้เล่นของคุณให้บรรลุเป้าหมายที่เฉพาะเจาะจงหรือเข้าร่วมในการประกวด`,
  _e = `ประกาศให้ทราบถึงการท้าทายแบบจำกัดเวลาสำหรับผู้เล่นเกมของคุณ`,
  ve = `เลือกประเภทของการท้าทาย`,
  ye = `กิจกรรมพิเศษของ %1$s`,
  be = `คุณสามารถใช้ประเภทกิจกรรมนี้เพื่อแสดงเกมของคุณด้วยวิธีพิเศษต่าง ๆ ในช่วงกิจกรรมนี้ได้ คลิกปุ่มข้อมูลด้านล่างเพื่อเรียนรู้เพิ่มเติมเกี่ยวกับวิธีการใช้กิจกรรมเหล่านี้ในช่วง%1$s`,
  xe = `ข้อมูลเพิ่มเติมเกี่ยวกับประเภทกิจกรรม`,
  Se = `คุณสามารถสร้างกิจกรรมประเภทนี้ได้สูงสุด 1 กิจกรรม`,
