  we = `คุณได้สร้าง %1$s กิจกรรมแล้ว`,
  Te = `อื่น ๆ`,
  Ee = `ในกรณีที่เราไม่อาจคาดหวังถึงกิจกรรมหรือข่าวสารพิเศษของคุณ`,
  De = `การอัปเดตเกม - ในกรณีส่วนใหญ่ จะมีการอัปเดตเกมด้วยเนื้อหาและการเปลี่ยนแปลงใหม่ ๆ โดยอัตโนมัติ`,
  Oe = `การวางจำหน่ายครั้งสำคัญ - ประกาศว่าเกมหรือเนื้อหาดาวน์โหลดของเกมจะออกวางจำหน่ายเมื่อใด`,
