  Me = `แช็ต - ผู้พัฒนากำลังจัดให้มีการแช็ต ซึ่งสมาชิกของทีมพัฒนาจะแลกเปลี่ยนความคิดเห็นและตอบคำถามของคุณ`,
  Ne = `กิจกรรมในชีวิตจริง - ผู้พัฒนากำลังจัดกิจกรรมที่จะไปปรากฏตัวด้วยตนเอง และชี้แจงรายละเอียดให้ทราบว่าคุณทราบว่าจะสามารถพบพวกเขาได้ที่ไหน`,
