  Ox = `กิจกรรมหรือประกาศที่สำคัญ ๆ สามารถมีภาพแบนเนอร์ที่แสดงอยู่บนหน้าร้านค้าของคุณในช่วงเวลาที่จัดกิจกรรมนั้น ๆ ได้ โดยอาร์ตเวิร์กสำหรับแบนเนอร์นี้จะแยกจากส่วนอื่น ๆ ในร้านค้า แบนเนอร์เหล่านี้จะต้องได้รับการอนุมัติจาก Valve ก่อน ดังนั้นโปรดติดต่อเจ้าหน้าที่ Valve ที่คุณติดต่อเป็นประจำก่อนที่จะอัปโหลด`,
